main().catch(e=>{fs.writeFileSync(path.join(out,'results.json'),JSON.stringify({results,errors,requests},null,2));console.error(e);console.error(JSON.stringify({out,errors}));process.exitCode=1}).finally(async()=>{await browser?.close();if(server)await new Promise(resolve=>server.close(resolve));});
